-- rowstile 0.1.0-dev: revoke_link_whole. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the same policy; what rowstile makes of it changed

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', 'b017d32ddf859df5', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM 'b017d32ddf859df5' THEN
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM 'b017d32ddf859df5' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only from here on; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- this migration starts from the policy the previous one left
DO $authz_guard$
DECLARE v_lock text;
BEGIN
  IF to_regclass('authz.policy_versions') IS NOT NULL THEN
    EXECUTE 'SELECT lock FROM authz.policy_versions ORDER BY id DESC LIMIT 1' INTO v_lock;
  END IF;
  IF v_lock = 'b017d32ddf859df5' THEN
    RAISE EXCEPTION 'rowstile: this database already holds what this migration brings (it ran here before, or rowstile dev or push took the database there): don''t run it, tell your migration tool it is applied [AZ607]'
      USING HINT = 'Prisma: prisma migrate resolve --applied <the migration''s folder>. Alembic: alembic stamp head. '
                   'Others, and why: rowstile help AZ607';
  ELSIF v_lock IS DISTINCT FROM 'f3a6fd3903c96ead' THEN
    RAISE EXCEPTION 'rowstile: this migration changes the policy the migration before it left (%), but the database has % [AZ607]',
      'f3a6fd3903c96ead', coalesce(v_lock, 'none')
      USING HINT = 'apply the migrations in order; a database changed with rowstile push or apply since needs the '
                   'migrations from the start (or rowstile apply of the policy the previous migration left) '
                   '(rowstile help AZ607)';
  END IF;
END $authz_guard$;

-- The app role must not be the policy's owner, nor a member of it: the rules would not hold for it
DO $ar$
DECLARE v_app name;
BEGIN
  SELECT a.rolname INTO v_app FROM pg_catalog.pg_roles a
  WHERE a.rolname = 'ms_app' AND NOT a.rolsuper AND pg_catalog.pg_has_role(a.oid, CURRENT_USER, 'MEMBER');
  IF v_app IS NOT NULL THEN
    RAISE EXCEPTION 'the app role % is the role that applies the policy (%), or a member of it: the rules would not hold for it [AZ624]', v_app, CURRENT_USER
      USING HINT = 'the policy''s owner skips row-level security, may turn it off, and is believed without a signature: the app connects as a role of its own, which owns nothing of the database';
  END IF;
END $ar$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

-- Turn a link off, by its id in authz.list_links: needs what unsharing it needs. A link in several relations is
-- judged in each as things are before any of it goes, and goes whole or not at all: taking it out of one relation
-- may change what the caller holds, and so what the next would be judged on
CREATE OR REPLACE FUNCTION authz.revoke_link(p_type text, p_id text, p_link text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_relations text[]; v record; v_found boolean := false;
BEGIN
  PERFORM authz_int.check_writable();
  p_id := authz_int.canon(p_type, p_id);
  v_relations := authz_int.link_relations(p_type, p_id);
  IF v_relations IS NULL THEN
    RAISE EXCEPTION 'you cannot turn off the links of % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  FOR v IN SELECT g.relation FROM authz.shares g
           WHERE g.object_type = p_type AND g.object_id = p_id AND g.subject_type = 'link'
             AND g.relation = ANY (v_relations) AND left(g.subject_id, 16) = p_link LOOP
    IF NOT authz_int.may_manage(p_type, p_id, v.relation, 'link') THEN
      RAISE EXCEPTION 'you cannot turn off link % of % % (you could not unshare it)', p_link, p_type, p_id
        USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    v_found := true;
  END LOOP;
  IF NOT v_found THEN
    RAISE EXCEPTION 'no link % on % %', p_link, p_type, p_id USING HINT = 'rowstile help AZ708';
  END IF;
  DELETE FROM authz.shares g WHERE g.object_type = p_type AND g.object_id = p_id AND g.subject_type = 'link'
    AND g.relation = ANY (v_relations) AND left(g.subject_id, 16) = p_link;
END $f$;

-- The partitions of a table rowstile watches and the tables that inherit from it: the triggers made above, on
-- each, for the rows stored there and the statements on it
DO $ch$
DECLARE r record;
BEGIN
  FOR r IN SELECT * FROM authz_int.child_triggers() LOOP
    EXECUTE r.stmt;
    EXECUTE pg_catalog.format('COMMENT ON TRIGGER %I ON %s IS %L', r.name, r.child, 'rowstile: the trigger of the table above, for the rows stored here');
  END LOOP;
END $ch$;

-- Privileges the policy doesn't give on rowstile's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = '"ms_app"'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = '"ms_app"'::regrole AND a.privilege_type = 'SELECT'
             AND c.relnamespace::regnamespace::text || '."' || replace(c.relname, '"', '""') || '"' = ANY (ARRAY['authz_gen."policy_lines"', 'authz_int."bot__manage"', 'authz_int."chat__add_members"', 'authz_int."chat__admin"', 'authz_int."chat__bot"', 'authz_int."chat__invitee"', 'authz_int."chat__join"', 'authz_int."chat__manage"', 'authz_int."chat__member"', 'authz_int."chat__owner"', 'authz_int."chat__post"', 'authz_int."chat__read"', 'authz_int."chat__setup"', 'authz_int."user__has_blocked"']::text[]))
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, '"ms_app"'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = '"ms_app"'::regrole
             AND '"' || replace(p.proname, '"', '""') || '"' = ANY (ARRAY['"ms.blocks:delete:items"', '"ms.blocks:delete:why"', '"ms.blocks:insert:items"', '"ms.blocks:insert:refuse"', '"ms.blocks:insert:why"', '"ms.blocks:rules:explain"', '"ms.bots:column id, owner_id:items"', '"ms.bots:column id, owner_id:why"', '"ms.bots:delete:items"', '"ms.bots:delete:why"', '"ms.bots:insert:items"', '"ms.bots:insert:refuse"', '"ms.bots:insert:why"', '"ms.bots:rules:explain"', '"ms.bots:update:items"', '"ms.bots:update:refuse"', '"ms.bots:update:why"', '"ms.chat_bots:delete:items"', '"ms.chat_bots:delete:why"', '"ms.chat_bots:insert:items"', '"ms.chat_bots:insert:refuse"', '"ms.chat_bots:insert:why"', '"ms.chat_bots:rules:explain"', '"ms.chats:column kind, created_by, created_at, last_seq:items"', '"ms.chats:column kind, created_by, created_at, last_seq:why"', '"ms.chats:delete:items"', '"ms.chats:delete:why"', '"ms.chats:insert:items"', '"ms.chats:insert:refuse"', '"ms.chats:insert:why"', '"ms.chats:rules:explain"', '"ms.chats:update:items"', '"ms.chats:update:refuse"', '"ms.chats:update:why"', '"ms.members:column chat_id, user_id, joined_at, joined_seq:items"', '"ms.members:column chat_id, user_id, joined_at, joined_seq:why"', '"ms.members:column last_read_seq:items"', '"ms.members:column last_read_seq:why"', '"ms.members:column role after:items"', '"ms.members:column role after:why"', '"ms.members:column role:items"', '"ms.members:column role:why"', '"ms.members:delete:items"', '"ms.members:delete:why"', '"ms.members:insert:items"', '"ms.members:insert:refuse"', '"ms.members:insert:why"', '"ms.members:rules:explain"', '"ms.members:update:items"', '"ms.members:update:refuse"', '"ms.members:update:why"', '"ms.messages:column body after:items"', '"ms.messages:column body after:why"', '"ms.messages:column chat_id, seq, sender_id, bot_id, cr_cb6d8c70"', '"ms.messages:column chat_id, seq, sender_id, bot_id, cr_f7ab4c37"', '"ms.messages:column deleted after:items"', '"ms.messages:column deleted after:why"', '"ms.messages:column deleted:items"', '"ms.messages:column deleted:why"', '"ms.messages:column edited_at:items"', '"ms.messages:column edited_at:why"', '"ms.messages:delete:items"', '"ms.messages:delete:why"', '"ms.messages:insert:items"', '"ms.messages:insert:refuse"', '"ms.messages:insert:why"', '"ms.messages:rules:explain"', '"ms.messages:update:items"', '"ms.messages:update:refuse"', '"ms.messages:update:why"', '"ms.users:column id, phone, created_at:items"', '"ms.users:column id, phone, created_at:why"', '"ms.users:rules:explain"', '"ms.users:update:items"', '"ms.users:update:refuse"', '"ms.users:update:why"']::text[]))
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = '"ms_app"'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.connection_check()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.list_links(text, bigint)', 'authz.revoke_link(text, bigint, text)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.create_role(text, bigint, text, text, text[])', 'authz.roles_of(text, bigint)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.break_glass(text, bigint, text, text, interval)', 'authz.start_review(text, bigint, timestamptz)', 'authz.who(text, uuid, text)', 'authz.explain(text, uuid, text, text)', 'authz.list_shares(text, uuid)', 'authz.list_links(text, uuid)', 'authz.revoke_link(text, uuid, text)', 'authz.create_link(text, uuid, text, timestamptz)', 'authz.create_role(text, uuid, text, text, text[])', 'authz.roles_of(text, uuid)', 'authz.request_access(text, uuid, text, text, interval)', 'authz.break_glass(text, uuid, text, text, interval)', 'authz.start_review(text, uuid, timestamptz)', 'authz.can(text, bigint, text)', 'authz.can(text, uuid, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.who_among(text, uuid, text, text[], text)', 'authz.perms(text, bigint)', 'authz.perms(text, uuid)', 'authz.share(text, text, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, bigint, text)', 'authz.share(text, text, text, text, uuid, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, uuid, text)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, bigint, text)', 'authz.share(text, bigint, text, text, uuid, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, bigint, text, text, uuid, text)', 'authz.share(text, uuid, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, uuid, text, text, text, text)', 'authz.share(text, uuid, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, uuid, text, text, bigint, text)', 'authz.share(text, uuid, text, text, uuid, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, uuid, text, text, uuid, text)']::regprocedure[])) LOOP
    EXECUTE g.stmt;
    v_taken := v_taken + 1;
  END LOOP;
  IF v_taken > 0 THEN
    RAISE WARNING 'took back % privileges on rowstile''s schemas that the policy doesn''t give (default privileges of the owner, or grants made since the last apply)', v_taken;
  END IF;
END $r$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz FROM PUBLIC;

GRANT USAGE ON SCHEMA authz, authz_gen TO "ms_app";

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz_gen FROM PUBLIC;

-- Tables never analyzed (made just now, or too small for autovacuum to have reached them) are planned
-- as ten pages of rows: a table of 6 rows as thousands. Through the rules' lookups that becomes an estimate of
-- hundreds of thousands, and Postgres compiles (JIT) and plans for reads of a few rows. ANALYZE reads a
-- sample (30,000 rows at most) and blocks neither reads nor writes.
DO $an$
DECLARE r record;
BEGIN
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.relkind = 'r' AND c.relpersistence <> 't' AND c.reltuples < 0
             AND pg_has_role(c.relowner, 'USAGE')
             AND (c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_int'))
                  OR c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"ms"."users"', '"ms"."blocks"', '"ms"."bots"', '"ms"."chats"', '"ms"."members"', '"ms"."chat_bots"', '"ms"."direct_blocks"', '"ms"."messages"']::text[]) x)) LOOP
    EXECUTE format('ANALYZE %s', r.tbl);
  END LOOP;
END $an$;

-- the policy now in force
INSERT INTO authz.policy_versions (action, policy, files, version, lock)
VALUES ('apply', $authz_policy$-- policy.authz: every access rule of the messenger. It reaches the database as the migrations rowstile
-- migrate writes into db/migrations; the backend has no permission checks of its own. Read it top to
-- bottom: people, bots, chats, then what each table allows.

app role ms_app

type user = ms.users (id uuid)
  self        : user = id                                   -- your own row
  has_blocked : user = ms.blocks(blocker_id -> blocked_id)  -- the people this person blocked
  can edit = self  -- your own profile

-- bots are services: they sign in with their own API keys (made by their owner) and post as themselves
type bot = ms.bots principal where {active}
  owner : user = owner_id
  can manage      = owner
  can manage_keys = owner

type chat = ms.chats
  member  : user = ms.members(chat_id -> user_id)
  admin   : user = ms.members(chat_id -> user_id) where {role in ('admin', 'owner')}
  owner   : user = ms.members(chat_id -> user_id) where {role = 'owner'}
  creator : user = created_by
  bot     : bot  = ms.chat_bots(chat_id -> bot_id)
  blocked : user = ms.direct_blocks(chat_id -> user_id)  -- a direct chat where one blocked the other
  invitee : link shared by invite                        -- invite links: anyone holding one

  can read = member or bot
  -- members post, unless blocked in a direct chat, or the group is for announcements and they aren't an admin
  can post   = (member and not blocked and ({not admins_only} or admin)) or bot
  can manage = admin and {kind = 'group'}                -- the title, the members, bots, invite links
  can invite = manage
  can join   = (invitee and {kind = 'group'}) or manage  -- (admins may make links, so they hold what links give)
  -- a chat just created, before anyone is in it: its creator sees it and adds themselves
  can setup = creator and {not exists (select 1 from ms.members m where m.chat_id = this.id)}
  -- adding people: admins of a group; the one who starts a direct chat adds the other person
  can add_members = manage or setup
                 or (creator and {kind = 'direct'} and {(select count(*) from ms.members m where m.chat_id = this.id) < 2})

-- a membership row: a person in a chat. Its key is (chat_id, user_id)
type membership = ms.members (chat_id, user_id uuid)
  chat   : chat = chat_id
  person : user = user_id

-- messages are numbered per chat; members read what was said since they joined, bots the whole chat
type message = ms.messages (chat_id, seq)
  chat     : chat = chat_id
  sender   : user = sender_id
  from_bot : bot  = bot_id

  can read   = chat.read and {seq > coalesce(ms.joined_seq(chat_id), 0)}  -- (by number, not by the clock)
  can edit   = sender and {not deleted and created_at > now() - interval '15 minutes'}
  can remove = sender or chat.manage                                      -- delete for everyone

type chat_bot = ms.chat_bots (chat_id, bot_id)
  chat : chat = chat_id
  bot  : bot  = bot_id

type block = ms.blocks (blocker_id uuid, blocked_id uuid)
  blocker : user = blocker_id

rules ms.users
  select                       : signed_in  -- to find people by phone number
  update                       : edit
  update id, phone, created_at : nobody

rules ms.bots
  select              : signed_in
  insert              : owner
  update              : manage
  update id, owner_id : nobody
  delete              : manage
  -- an account is deleted by the tables' owner (no rule lets the app): its bots go with it
  cascade from ms.users

rules ms.chats
  select                                        : read or join or setup
  insert                                        : creator
  update                                        : manage
  update kind, created_by, created_at, last_seq : nobody
  delete                                        : owner and {kind = 'group'}
  -- a chat outlives the account that made it
  cascade from ms.users

rules ms.members
  -- added by someone who may (not as an admin unless they are one; as the owner only when the chat is set
  -- up), never someone who blocked you;
  -- or yourself, with an invite link
  insert                                         : (chat.add_members and ({role = 'member'} or chat.setup
                                                or (chat.manage and {role <> 'owner'}))
                                               and not person.has_blocked)
                                                or (chat.join and person and {role = 'member'})
  select                                         : chat.read
  update                                         : chat.manage or person
  update role                                    : chat.manage and {role <> 'owner'}              -- nobody demotes the owner
  update role after                              : {role <> 'owner'}                              -- nor makes another
  update last_read_seq                           : person
  update chat_id, user_id, joined_at, joined_seq : nobody
  delete                                         : (person or chat.manage) and {role <> 'owner'}  -- leave, or be removed; never the owner
  -- a group deleted by its owner takes every membership in it; an account deleted, its memberships
  cascade from ms.chats
  cascade from ms.users

rules ms.messages
  select                                             : read
  insert                                             : chat.post and ((sender and {bot_id is null}) or (from_bot and {sender_id is null}))
  update                                             : edit or remove
  update body after                                  : (edit and {not deleted}) or {deleted and body = ''}
  update deleted                                     : remove
  update deleted after                               : {deleted}  -- no undelete
  update edited_at                                   : edit       -- marked edited only while it may be edited
  update chat_id, seq, sender_id, bot_id, created_at : nobody
  delete                                             : nobody     -- messages are deleted for everyone, not removed
  -- a group deleted by its owner takes its messages, which no rule removes; a deleted account's or bot's
  -- messages stay, from nobody
  cascade from ms.chats
  cascade from ms.users
  cascade from ms.bots

rules ms.chat_bots
  select : chat.read
  insert : chat.manage and bot.manage and {added_by = authz.uid()}  -- your own bots, into chats you manage
  delete : chat.manage or bot.manage
  -- a deleted chat or bot takes the bot out of the chat; a deleted account leaves the bots it added
  cascade from ms.chats
  cascade from ms.bots
  cascade from ms.users

rules ms.blocks
  select : blocker
  insert : blocker
  delete : blocker
  -- an account deleted, the blocks it made and those made against it
  cascade from ms.users (blocker_id)
  cascade from ms.users (blocked_id)
$authz_policy$,
  $authz_files${}$authz_files$::jsonb, '0.1.0-dev+03f6a4f43c74', 'b017d32ddf859df5');
